/**
 * Rundeck Node - Version 1.1
 * Manage Rundeck API
 */


export interface RundeckV11Params {
  resource?: 'job';
  operation?: 'execute' | 'getMetadata';
/**
 * The job ID to execute
 * @displayOptions.show { operation: ["execute"], resource: ["job"] }
 */
    jobid: string | Expression<string>;
/**
 * Arguments
 * @displayOptions.show { operation: ["execute"], resource: ["job"] }
 * @default {}
 */
    arguments?: {
        /** Arguments
     */
    arguments?: Array<{
      /** Name
       */
      name?: string | Expression<string>;
      /** Value
       */
      value?: string | Expression<string>;
    }>;
  };
/**
 * Filter Rundeck nodes by name
 * @displayOptions.show { operation: ["execute"], resource: ["job"] }
 */
    filter?: string | Expression<string>;
}

export interface RundeckV11Credentials {
  rundeckApi: CredentialReference;
}

interface RundeckV11NodeBase {
  type: 'n8n-nodes-base.rundeck';
  version: 1.1;
}

export type RundeckV11ParamsNode = RundeckV11NodeBase & {
  config: NodeConfig<RundeckV11Params> & { credentials?: RundeckV11Credentials };
};

export type RundeckV11Node = RundeckV11ParamsNode;